//! Small text helpers shared by the generators that were written against Kotlin's standard library.
//!
//! The shell scripts and TOML files the core emits used to be Kotlin raw strings run through
//! `trimIndent()`; reproducing that function exactly keeps the generated bytes identical to what the
//! Kotlin apps produced (a script with one line shifted right can break a heredoc on the VPS).

/// Kotlin `lines()`: splits on `\r\n`, `\n` and `\r`; an empty string is one empty line.
pub fn kotlin_lines(s: &str) -> Vec<&str> {
    let mut out = Vec::new();
    let bytes = s.as_bytes();
    let mut start = 0;
    let mut i = 0;
    while i < bytes.len() {
        match bytes[i] {
            b'\n' => {
                out.push(&s[start..i]);
                i += 1;
                start = i;
            }
            b'\r' => {
                out.push(&s[start..i]);
                i += if bytes.get(i + 1) == Some(&b'\n') {
                    2
                } else {
                    1
                };
                start = i;
            }
            _ => i += 1,
        }
    }
    out.push(&s[start..]);
    out
}

/// Kotlin `isBlank()`.
pub fn is_blank(s: &str) -> bool {
    s.chars().all(char::is_whitespace)
}

/// Kotlin `String.trimIndent()`: removes the common minimal indent of the non-blank lines from every
/// line and drops the first and the last line when they are blank. Lines are re-joined with `\n`.
pub fn trim_indent(s: &str) -> String {
    let lines = kotlin_lines(s);
    let min_indent = lines
        .iter()
        .filter(|l| !is_blank(l))
        .map(|l| l.chars().take_while(|c| c.is_whitespace()).count())
        .min()
        .unwrap_or(0);
    let last = lines.len() - 1;
    lines
        .iter()
        .enumerate()
        .filter(|(i, l)| !((*i == 0 || *i == last) && is_blank(l)))
        .map(|(_, l)| l.chars().skip(min_indent).collect::<String>())
        .collect::<Vec<_>>()
        .join("\n")
}

/// Wraps `s` in single quotes for safe shell interpolation, escaping any embedded single quote.
pub fn shell_single_quote(s: &str) -> String {
    format!("'{}'", s.replace('\'', r"'\''"))
}

/// Splits a leading emoji (if any) off a name: `("🇫🇮", "Helsinki")` for `"🇫🇮 Helsinki"`. Keeps
/// multi-codepoint glyphs whole: flags (regional-indicator pairs), ZWJ sequences, variation
/// selectors, skin tones and keycaps. Without a leading emoji: `(default_emoji, "")`.
pub fn parse_emoji_and_name(raw_name: &str, default_emoji: &str) -> (String, String) {
    let trimmed = raw_name.trim();
    match trimmed.chars().next() {
        Some(first) if is_emoji_code_point(first) => {}
        _ => return (default_emoji.to_string(), String::new()),
    }
    let end = trimmed
        .char_indices()
        .find(|(_, c)| !is_emoji_code_point(*c) && !is_emoji_joiner(*c))
        .map_or(trimmed.len(), |(index, _)| index);
    (
        trimmed[..end].to_string(),
        trimmed[end..].trim().to_string(),
    )
}

fn is_emoji_code_point(c: char) -> bool {
    matches!(
        u32::from(c),
        0x1F1E6..=0x1F1FF // regional indicators (flags)
            | 0x1F300..=0x1FAFF // main emoji blocks
            | 0x2600..=0x27BF // misc symbols + dingbats
            | 0x2B00..=0x2BFF // stars, arrows
            | 0x1F000..=0x1F0FF // mahjong, dominoes, cards
            | 0x2122
            | 0x2139
            | 0x2190..=0x21FF // arrows
            | 0x2300..=0x23FF // technical (⌚⏰ etc.)
    )
}

fn is_emoji_joiner(c: char) -> bool {
    matches!(
        u32::from(c),
        0x200D // zero-width joiner
            | 0xFE0F | 0xFE0E // variation selectors
            | 0x20E3 // combining keycap
            | 0x1F3FB..=0x1F3FF // skin-tone modifiers
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn trim_indent_matches_kotlin() {
        assert_eq!(
            trim_indent("\n        a\n          b\n\n        c\n    "),
            "a\n  b\n\nc"
        );
        assert_eq!(trim_indent(""), "");
        assert_eq!(trim_indent("x"), "x");
        // A line with no indent anywhere (here appended after the raw string) keeps everyone else's.
        assert_eq!(trim_indent("\n    a\n    \nb"), "    a\n    \nb");
        assert_eq!(kotlin_lines("a\r\nb\rc\n"), ["a", "b", "c", ""]);
    }

    #[test]
    fn single_quote() {
        assert_eq!(shell_single_quote("it's"), r"'it'\''s'");
    }
}
